        margin: 0 0 0.35rem;
        color: var(--muted);
        font-size: 0.92rem;
      }

      .meta-row dd {
        margin: 0;
        font-size: 1.05rem;
        font-weight: 700;
      }

      .status {
        min-height: 1.6rem;
        margin-top: 1rem;
        font-weight: 600;
      }

      .status[data-state="success"] {
        color: #0f7a39;
      }

