        display: none;
        align-items: center;
        justify-content: center;
        flex-direction: column;
        gap: 0.85rem;
        aspect-ratio: 16 / 10;
        border-radius: 22px;
        border: 1px dashed rgba(15, 23, 42, 0.18);
        background:
