      dialog {
        width: min(92vw, 420px);
        padding: 0;
        border: none;
        border-radius: 24px;
        background: var(--surface-strong);
        color: var(--text);
        box-shadow: 0 32px 80px rgba(15, 23, 42, 0.28);
      }

      dialog::backdrop {
        background: rgba(15, 23, 42, 0.5);
        backdrop-filter: blur(8px);
      }

      .dialog-panel {
        padding: 1.5rem;
      }

      .dialog-icon {
        display: inline-flex;
        align-items: center;
        justify-content: center;
        width: 3rem;
        height: 3rem;
        border-radius: 999px;
        margin-bottom: 1rem;
        background: #fff1f1;
        color: var(--danger-strong);
        font-size: 1.25rem;
      }

      .dialog-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.75rem;
        margin-top: 1.5rem;
      }

      .dialog-actions button {
        flex: 1 1 160px;
      }

      @media (max-width: 860px) {
        .hero {
          grid-template-columns: 1fr;
        }

        .preview-meta {
          flex-direction: column;
        }
