         letter-spacing: 0.08em;
         text-transform: uppercase;
       }

       .badge {
         padding: 0.55rem 0.9rem;
         border: 1px solid var(--border);
         border-radius: 999px;
         background: rgba(255, 255, 255, 0.7);
         color: var(--muted);
         font-size: 0.95rem;
       }

       main {
         outline: none;
       }

       .hero {
         display: grid;
         grid-template-columns: minmax(0, 1.35fr) minmax(280px, 0.9fr);
         gap: 1.5rem;
         align-items: stretch;
