       }

       .preview-meta {
         display: flex;
         justify-content: space-between;
         align-items: start;
         gap: 1rem;
         padding-top: 1.2rem;
       }

       .eyebrow {
         margin: 0 0 0.5rem;
         color: var(--primary);
         font-size: 0.9rem;
         font-weight: 700;
         letter-spacing: 0.04em;
         text-transform: uppercase;
