       h1 {
         margin: 0;
         font-size: clamp(2rem, 3vw, 3.1rem);
         line-height: 1.05;
       }

       .supporting-copy,
       .meta-copy,
       .sidebar-copy,
       .dialog-copy,
       .status {
         color: var(--muted);
         line-height: 1.6;
       }

       .supporting-copy {
         margin: 0.9rem 0 0;
         max-width: 46ch;
       }

       .preview-actions {
         display: flex;
         flex-wrap: wrap;
         gap: 0.85rem;
         margin-top: 1.25rem;
       }

       button {
         appearance: none;
         border: 0;
         border-radius: 999px;
         font: inherit;
         font-weight: 700;
         cursor: pointer;
         transition:
           transform 0.18s ease,
           background-color 0.18s ease,
           box-shadow 0.18s ease,
           border-color 0.18s ease;
       }

       button:hover {
         transform: translateY(-1px);
       }

       button:focus-visible,
       dialog:focus-visible {
         outline: 3px solid #0f172a;
         outline-offset: 3px;
       }

       .primary-action,
       .secondary-action,
       .danger-action,
       .danger-primary {
         min-height: 48px;
         padding: 0.9rem 1.3rem;
