         font-size: 0.92rem;
       }

       .meta-row dd {
         margin: 0;
         font-size: 1.05rem;
         font-weight: 700;
       }

       .status {
         min-height: 1.6rem;
         margin-top: 1rem;
         font-weight: 600;
       }

       .status[data-state="success"] {
         color: #0f7a39;
       }

       .empty-state {
         display: none;
         align-items: center;
         justify-content: center;
         flex-direction: column;
         gap: 0.85rem;
         aspect-ratio: 16 / 10;
         border-radius: 22px;
         border: 1px dashed rgba(15, 23, 42, 0.18);
         background:
           linear-gradient(135deg, rgba(255, 255, 255, 0.82), rgba(244, 247, 255, 0.95));
         color: var(--muted);
         text-align: center;
         padding: 1.5rem;
